package module6;

import de.fhpotsdam.unfolding.core.Coordinate;
import de.fhpotsdam.unfolding.providers.EsriProvider;

/** Esri "World Light Gray Canvas" tiles served over HTTPS.
 *
 *  The tile URLs generated by Unfolding's built-in Esri provider use plain
 *  http://.  The Esri server redirects those requests to https://, and the
 *  old image loader bundled with Processing does not follow a redirect that
 *  changes the protocol, so every tile fails.  Overriding getTileUrls() with
 *  the HTTPS address fixes the basemap without changing anything else.
 */
public class HttpsEsriProvider extends EsriProvider.WorldGrayCanvas {

	private static final String TILE_BASE =
			"https://server.arcgisonline.com/ArcGIS/rest/services/"
			+ "Canvas/World_Light_Gray_Base/MapServer/tile/";

	@Override
	public String[] getTileUrls(Coordinate coordinate) {
		return new String[] { TILE_BASE + getZoomString(coordinate) + ".jpg" };
	}
}
